{
  "anti_collapse": {
    "decisive_reason": "After source framing is removed the procedure is ordinary material-feature inspection using the supplied probe to record response/nonresponse and return to ordinary collation; substitution by close inspection of deletions, insertions and paper features loses no warrant, decomposition or follow-up rule.",
    "departures": {
      "action": {
        "rationale": "Maintain anomaly catalogue and apply available probe within documented damage limits, compare with blanks and known positives, record response/nonresponse is the same epistemic act as ordinary compare of witnesses, handwriting, deletions, insertions and paper features. Target states each procedure has same access to probe, witnesses and controls. Control comparison is standard caution, not a new modeling, selection or intervention operation.",
        "status": "absent"
      },
      "inferential_warrant": {
        "rationale": "Response supports presence/location of responsive material, not a particular former reading, author or date; separately supplied overlay relation makes actual underlayer a bounded pre-overwriting constraint; identifying or dating requires independent collation. This repeats ordinary patterns: variants and material features constrain order without equating narrative with composition order, and a local reading or physical mark does not alone establish whole history.",
        "status": "absent"
      },
      "next_inquiry": {
        "rationale": "Return to ordinary witness collation or correspondence with localized finding, with no new follow-up-selection rule. This is ordinary next actions: collate additional witnesses, inspect material features, consult dated correspondence, retain competing sequences where incomplete. Budget for one follow-up does not create a rule for choosing it.",
        "status": "absent"
      },
      "observable": {
        "rationale": "Otherwise invisible localized material response plus blank and positive-control responses functions as a material feature of the patch with erased underlayer. Ordinary evidence already includes material features, draft variants and dated witnesses. That ordinary reading does not reveal it is sensitivity difference, not a new evidential kind; no claim of particular reading, author or date is added.",
        "status": "absent"
      },
      "problem_decomposition": {
        "rationale": "Procedure explicitly keeps ordinary patch, witness and revision-account units with no new complete-history model. No re-partitioning of revision/assembly question is introduced.",
        "status": "absent"
      }
    },
    "formalization": {
      "merely_makes_native_reasoning_explicit": "yes",
      "new_epistemic_constraint": null,
      "rationale": "Limits that interfering materials can respond, degradation can prevent response, damage limits apply, and that nonresponse is not proof of no prior writing merely make explicit ordinary caution to retain competing sequences when evidence is incomplete. No new stopping condition, evidence-selection rule, falsification condition, intervention requirement, minimality criterion or next-step constraint with operational consequence is added."
    },
    "materiality": {
      "rationale": "No change in how inquiry proceeds: same observation-recording logic, same cautious constraint, same units and same return to collation/correspondence. Added sensitivity and systematic catalogue are more steps with same epistemic logic and bookkeeping, which is insufficient for materiality.",
      "status": "immaterial"
    },
    "native_reduction": {
      "closest_native_equivalent": "Close comparison of manuscript witnesses, handwriting, deletions, insertions and paper features at the patch, recording anomaly presence/absence, constraining order with dated correspondence and retaining competing assembly sequences where incomplete",
      "collapses_without_loss": "yes",
      "lost_if_reduced": [],
      "rationale": "Replacing probe-record step with ordinary material-feature inspection loses no important operation, observable kind, warrant, decomposition or subsequent inquiry. Blanks, known positives and damage limits document the same observation; overlay plus independent collation requirement is already ordinary need for independent justification."
    },
    "status": "CLEAR_COLLAPSE",
    "uncertainty": [
      "Baseline is scoped authored hypothesis, not verified practitioner consensus, so exact boundary of ordinary material-feature inspection is uncertain",
      "Manuscript scholars differ in quantitative training and familiarity with blanks/positives control language, but technical unfamiliarity alone was not counted as epistemic departure"
    ]
  },
  "case_id": "N004"
}
